from pathlib import Path
import os,stat,subprocess
root=Path('/srv/projects/telegram-robot-leads')
paths={
 'old-state':Path('/var/lib/telegram-robot-leads'),
 'new-state':root/'data',
 'old-vault':Path('/root/project-secrets/telegram-robot-leads'),
 'new-vault':root/'private',
}
for tag,p in paths.items():
 if p.exists() or p.is_symlink():
  st=p.lstat()
  ptype='symlink' if p.is_symlink() else 'dir' if p.is_dir() else 'other'
  print('PATH',tag,ptype,'UID',st.st_uid,'GID',st.st_gid,'MODE',oct(st.st_mode&0o777),'DEV',st.st_dev,'INODE',st.st_ino)
  if p.is_dir():
   r=subprocess.run(['du','-x','-s','-B1',str(p)],capture_output=True,text=True,timeout=22)
