 else:print('PATH',tag,'ABSENT')
assert root.is_dir() and not root.is_symlink()
for tag in ('old-state','old-vault'):
 p=paths[tag]
 if not p.is_dir() or p.is_symlink():raise RuntimeError('Source not a real dir: '+tag)
 if p.stat().st_uid!=0 or p.stat().st_mode&0o077:raise RuntimeError('Unexpected private source modes')
print('===FILES METADATA===')
for tag in ('old-state','old-vault'):
 p=paths[tag]
 n=0
 for cur,dirs,files in os.walk(p,followlinks=False):
  for f in files:
   q=Path(cur)/f
   if q.is_symlink():print('SYMLINK_CHILD',tag);continue
   n+=1
   if q.suffix in ('.session','.session-journal'):
    s=q.stat()
    print('SESSION_METADATA',tag,'BYTE_SIZE',s.st_size,'MODE',oct(s.st_mode&0o777))
 print('FILE_COUNT',tag,n)
print('===RUNTIME CODE REFERENTIAL GUARDS===')
terms=['realpath(','.resolve(','.is_symlink(', 'is_symlink(', 'VAULT', 'STATE_ROOT', 'DATA_ROOT', '/var/lib/telegram-robot-leads','/root/project-secrets/telegram-robot-leads']
files=['main.py','scripts/telethon_sessions.py','scripts/safe_runtime.py','scripts/deploy_project_only.py','scripts/public_group_discovery.py','scripts/lead_health.py','scripts/member_groups.py','scripts/operation_policy.py']
for name in files:
 p=root/name
 if not p.is_file():continue
 lines=p.read_text(errors='replace').splitlines()
 hits=[]
 for i,line in enumerate(lines,1):
  if any(k in line for k in terms):
   if len(line)>300:continue
   hits.append((i,line))
 print('FILE_GUARDS',name,'HITS',len(hits))
 for lineno,line in hits[:25]:print('LINE',lineno,line[:230])
print('PREFLIGHT_DATA_PRIVATE=PASS')
